package com.kaizer.ps5simulator.data.model

/**
 * A game entry in the simulated console library.
 *
 * Art paths point into APK assets (`games/<id>/...`). All artwork shipped with the
 * app is original concept art generated by tools/gen_assets.py — never publisher
 * material — and the UI labels it accordingly.
 */
data class Game(
    val id: String,
    val title: String,
    val genre: String,
    val publisher: String,
    val year: Int,
    val sizeGb: Double,
    val description: String,
    val tagline: String,
    val accent: Int,
    val deep: Int,
    val index: Int,
) {
    val titleInitials: String
        get() = title.split(" ").filter { it.length > 1 }.take(2)
            .joinToString("") { it.first().uppercase() }

    val artwork: String get() = "file:///android_asset/games/$id/background.jpg"
    val coverArt: String get() = "file:///android_asset/games/$id/cover.jpg"
    val cardArt: String get() = "file:///android_asset/games/$id/card.jpg"
    val heroArt: String get() = "file:///android_asset/games/$id/hero.png"

    fun shot(n: Int): String = "file:///android_asset/games/$id/shot$n.jpg"

    /** Placeholder copy shown on every screen that displays generated key art. */
    val artNotice: String get() = "ORIGINAL CONCEPT ART — SIMULATOR LIBRARY"

    companion object {
        const val ROW_LIMIT = 30
    }
}

enum class LibrarySort(val label: String, val key: String) {
    RECENT("Recent", "recent"),
    NAME("Name (A - Z)", "name"),
    SIZE("Size", "size"),
    RELEASE("Release year", "release"),
}

enum class LibraryFilter(val label: String, val key: String) {
    ALL("All", "all"),
    INSTALLED("Installed on console", "installed"),
    FAVORITES("Favourites", "favourites"),
}
